import functools
import time


def retry(max_retries=3, delay=1):
    """
    A decorator that retries a function up to max_retries times when it raises an exception.

    Args:
        max_retries (int): Maximum number of retries (default: 3).
        delay (float): Delay in seconds between retries (default: 1).

    Returns:
        A decorator function.
    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            last_exception = None
            for attempt in range(max_retries + 1):  # +1 because the first try is not a retry
                try:
                 return func(*args, **kwargs)
                except Exception as e:
                 last_exception = e
                 if attempt < max_retries:
                 time.sleep(delay)
            raise

